UPDATE AUD_TASK_ATTEMPTS AS a SET HEARTBEAT_AT=HEARTBEAT_AT WHERE a.ATTEMPT_ID=:attempt_id AND a.TASK_RUN_ID=:task_run_id AND a.OWNER_ID=:owner AND a.STATUS IN ('CLAIMED','RUNNING') AND a.LEASE_EXPIRES_AT>:now AND NOT EXISTS (SELECT 1 FROM AUD_TASK_ATTEMPTS newer WHERE newer.TASK_RUN_ID=a.TASK_RUN_ID AND newer.ATTEMPT_NUMBER>a.ATTEMPT_NUMBER) RETURNING ATTEMPT_ID AS attempt_id
